"""Read-only MySQL 5.6+/ProcessMaker 3.2+ case adapter. No SQL generated by an LLM."""

from contextlib import contextmanager
from datetime import datetime, time
from zoneinfo import ZoneInfo
import re, json, ssl
import jdatetime
from . import setup_console as setup
from . import native_access
from .security import Principal

MEETING_PROCESS = "f7f263ea31d8731d212820f220c65a48"
ACTION_PROCESS = "cd66870095907431106b6dd110e06fa7"
MAX_MEETINGS = 2000
MAX_CASE_BYTES = 8 * 1024 * 1024
DATABASE_PATTERN = r"^(?:wf_[A-Za-z0-9_]{1,48}|bitnami_pm)$"


class ProductionUnavailable(Exception):
    pass


class ProductionAccessDenied(Exception):
    pass


class EmployeeMappingRequired(ProductionAccessDenied):
    pass


@contextmanager
def open_production(config=None):
    import pymysql

    c = config if config is not None else setup.get_setting("mysql") or {}
    if config is None and c.get("enabled") is False:
        raise ProductionUnavailable("ProcessMaker MySQL connection is disabled")
    if not all(c.get(k) for k in ("host", "database", "username", "password")):
        raise ProductionUnavailable("ProcessMaker MySQL is not configured")
    if not re.fullmatch(DATABASE_PATTERN, c["database"]):
        raise ProductionUnavailable("A native ProcessMaker workspace database is required")
    if c["username"].casefold() in ("root", "admin"):
        raise ProductionUnavailable("Use a dedicated SELECT-only account")
    try:
        con = pymysql.connect(
            host=c["host"],
            port=int(c.get("port", 3306)),
            user=c["username"],
            password=c["password"],
            database=c["database"],
            charset="utf8mb4",
            connect_timeout=8,
            read_timeout=15,
            write_timeout=8,
            autocommit=False,
            ssl=(
                ssl.create_default_context(cadata=c.get("ca_pem") or None)
                if c.get("tls", True)
                else None
            ),
        )
        if c.get("tls", True) and not isinstance(con._sock, ssl.SSLSocket):
            raise ProductionUnavailable("MySQL did not negotiate TLS")
        with con.cursor() as cur:
            cur.execute("SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ")
            cur.execute("START TRANSACTION READ ONLY")
        yield con
    except (pymysql.MySQLError, ssl.SSLError) as exc:
        raise ProductionUnavailable("Read-only ProcessMaker MySQL unavailable") from exc
    finally:
        if "con" in locals():
            con.rollback()
            con.close()


def query(con, sql, args=()):
    with con.cursor() as cur:
        cur.execute(sql, args)
        return cur.fetchall()


def directory(con):
    rows = query(
        con,
        "SELECT u.USR_UID,u.USR_FIRSTNAME,u.USR_LASTNAME,u.USR_EMAIL,u.USR_STATUS,d.DEP_TITLE,u.USR_USERNAME FROM USERS u LEFT JOIN DEPARTMENT d ON d.DEP_UID=u.DEP_UID",
    )
    if len(rows) > 5000:
        raise ProductionUnavailable("Directory exceeds configured bounds")
    return {
        str(r[0]).strip().lower(): {
            "name": str(r[1] or "") + " " + str(r[2] or ""),
            "email": str(r[3] or ""),
            "active": str(r[4] or "").strip().upper() == "ACTIVE",
            "unit": str(r[5] or "") if len(r) > 5 else "",
            "username": str(r[6] or "").strip() if len(r) > 6 else "",
        }
        for r in rows
    }


def verified_scope(con, principal, source_id=None):
    if not isinstance(principal, Principal):
        raise ProductionAccessDenied("Verified identity required")
    data = native_access.read()
    if data["tenant_id"] != str(principal.tenant_id):
        raise EmployeeMappingRequired("Organization is not mapped")

    avan_users = {
        u.get("subject"): u for u in data["users"]
        if u.get("subject") and u.get("enabled")
    }
    current = avan_users.get(principal.subject)
    if not current:
        raise EmployeeMappingRequired("Active AVAN account required")

    from .user_bpms_bindings import (
        default_processmaker_source_id, bindings_by_source,
        processmaker_profile, BindingError,
    )
    source_id = source_id or default_processmaker_source_id(principal.subject)
    if not source_id:
        raise EmployeeMappingRequired(
            "Select an explicitly bound ProcessMaker source; unscoped access is unavailable"
        )
    try:
        profile = processmaker_profile(source_id)
    except BindingError as exc:
        raise ProductionAccessDenied("ProcessMaker source is not available") from exc

    bound = bindings_by_source(source_id)

    def external_uid(user):
        # Runtime authorization is binding-only. Legacy pm_uid fields are never
        # accepted as access evidence; they exist solely for one-time migration.
        binding = bound.get(user.get("subject"))
        if binding and binding.get("status") == "active":
            return str(binding.get("external_user_id") or "").strip().lower()
        return ""

    current_uid = external_uid(current)
    users = directory(con)
    if not current_uid or not users.get(current_uid, {}).get("active"):
        raise EmployeeMappingRequired("Active ProcessMaker binding required")

    role = current.get("role")
    platform_godadmin = role == "GodAdmin" and setup.is_godadmin(principal)
    if role not in ("Expert", "Manager", "SysAdmin", "GodAdmin"):
        raise ProductionAccessDenied("Role not authorized")
    if role == "GodAdmin" and not platform_godadmin:
        raise ProductionAccessDenied("GodAdmin identity is not bound")
    if role == "SysAdmin" and "SysAdmin" not in principal.roles:
        raise ProductionAccessDenied("Role not authorized")

    visible_subjects = {principal.subject}
    visible = {current_uid}

    if role == "Manager":
        for _ in range(32):
            more_subjects = set()
            more_uids = set()
            for subject, user in avan_users.items():
                uid = external_uid(user)
                if not uid or not users.get(uid, {}).get("active"):
                    continue
                manager_subject = user.get("manager_subject")
                if manager_subject and manager_subject in visible_subjects:
                    more_subjects.add(subject)
                    more_uids.add(uid)
            if more_subjects <= visible_subjects and more_uids <= visible:
                break
            visible_subjects |= more_subjects
            visible |= more_uids
        else:
            raise ProductionAccessDenied("Hierarchy depth exceeded")
    elif role in ("SysAdmin", "GodAdmin"):
        for subject, user in avan_users.items():
            uid = external_uid(user)
            if uid and users.get(uid, {}).get("active"):
                visible_subjects.add(subject)
                visible.add(uid)

    staff = {}
    for subject, user in avan_users.items():
        uid = external_uid(user)
        if uid and users.get(uid, {}).get("active"):
            staff[uid] = user

    # Keep the authoritative ProcessMaker identity while exposing the bound
    # AVAN display identity as an additional alias for conversational matching.
    # This lets a user say e.g. «مدیر فروش» while writes still use only the
    # exact external ProcessMaker UID.
    resolved_users = {}
    for uid, person in users.items():
        avan = staff.get(uid) or {}
        resolved_users[uid] = {
            **person,
            "avan_name": str(avan.get("name") or "").strip()[:240],
            "avan_username": str(avan.get("username") or "").strip()[:180],
            "avan_department": str(avan.get("department_name") or "").strip()[:240],
        }
    users = resolved_users

    from .production_license import entitlement, ProductionLicenseDenied
    try:
        licensed = entitlement(
            tenant_id=data["tenant_id"], company_name=data["company_name"]
        )
    except ProductionLicenseDenied as exc:
        raise ProductionAccessDenied("Valid license required") from exc
    # AVAN account grants are independent from BPMS bindings and can only
    # narrow the organization's licensed module set.
    effective=native_access.effective_modules(current,licensed["modules"])
    lic={**licensed,"modules":effective}

    mysql = profile.get("mysql") or {}
    return {
        "license": lic,
        "source_id": source_id,
        "source_name": profile.get("name") or "ProcessMaker",
        "timezone": mysql.get("timezone", "Asia/Tehran"),
        "external_user_id": current_uid,
        "name": current.get("name") or users[current_uid]["name"],
        "department": current.get("department_name") or users[current_uid].get("unit"),
        "role": role,
        "company": data["company_name"],
        "tenant_id": data["tenant_id"],
        "visible_uids": visible,
        "directory": users,
        "staff": staff,
    }

def decode_case(raw):
    """phpserialize never instantiates PHP/Python classes; object tokens are rejected."""
    import phpserialize

    if isinstance(raw, str):
        raw = raw.encode("utf-8")
    if not isinstance(raw, bytes) or len(raw) > MAX_CASE_BYTES:
        raise ProductionUnavailable("Invalid case size")
    try:
        value = phpserialize.loads(raw, decode_strings=True, object_hook=None)
        if not isinstance(value, dict):
            raise ValueError("Case root is not an array")
        return value
    except (ValueError, TypeError, UnicodeError, RecursionError) as exc:
        raise ProductionUnavailable("Unreadable native case data") from exc


def history(value):
    if not value:
        return []
    try:
        result = json.loads(value) if isinstance(value, str) else value
        if not isinstance(result, list) or any(not isinstance(r, dict) for r in result):
            raise ValueError("Invalid history")
        return result
    except (ValueError, TypeError) as exc:
        raise ProductionUnavailable("Unreadable native history") from exc


def grid(value):
    return [
        r
        for r in (
            value.values()
            if isinstance(value, dict)
            else value if isinstance(value, list) else []
        )
        if isinstance(r, dict)
    ]


def cell(row, key, index=0):
    if key in row:
        return row[key]
    for name, value in row.items():
        if isinstance(name, str) and name.casefold() == key.casefold():
            return value
    return row.get(index if 0 in row else index + 1, "")


def text(value):
    if isinstance(value, dict):
        value = value.get("value", value.get("uid", ""))
    return str(value if value is not None else "").strip()


def iso(value, clock=None, end_day=False, timezone_name=None):
    v = (
        text(value)
        .translate(str.maketrans("۰۱۲۳۴۵۶۷۸۹٠١٢٣٤٥٦٧٨٩", "01234567890123456789"))
        .replace("/", "-")
    )
    if not v:
        return None
    try:
        if clock:
            v = v[:10] + " " + text(clock)
        if int(v[:4]) < 1700:
            y, m, d = map(int, v[:10].split("-"))
            v = jdatetime.date(y, m, d).togregorian().isoformat() + v[10:]
        dt = datetime.fromisoformat(v)
        if len(v) == 10 and end_day:
            dt = datetime.combine(dt.date(), time(23, 59, 59))
        if dt.tzinfo is None:
            dt = dt.replace(
                tzinfo=ZoneInfo(
                    timezone_name
                    or (setup.get_setting("mysql") or {}).get("timezone", "Asia/Tehran")
                )
            )
        return dt.isoformat()
    except (ValueError, TypeError):
        return None


def members(d):
    return (
        {text(d.get("MTG_ChairUserUID")), text(d.get("MTG_SecretaryUserUID"))}
        | {
            text(cell(r, "MTG_ParticipantUserUID", 0))
            for r in grid(d.get("MTG_Participants"))
        }
        | {text(cell(r, "MTG_ActionOwnerUID", 3)) for r in grid(d.get("MTG_Actions"))}
    )


def _meeting(row, d):
    held = text(d.get("MTG_MeetingHeld"))
    held = held if held in ("Held", "NotHeld") else None
    attendance = []
    for participant in grid(d.get("MTG_Participants")):
        status = text(cell(participant, "MTG_AttendanceStatus", 4))
        clock = text(cell(participant, "MTG_AttendanceTime", 5)).translate(
            str.maketrans("۰۱۲۳۴۵۶۷۸۹٠١٢٣٤٥٦٧٨٩", "01234567890123456789")
        )
        attendance.append({
            "participant_uid": text(cell(participant, "MTG_ParticipantUserUID", 0)),
            "status": status if held != "NotHeld" and status in ("Present", "Absent", "Excused") else None,
            "arrival_time_local": clock if held != "NotHeld" and status == "Present" and re.fullmatch(r"(?:[01]\d|2[0-3]):[0-5]\d", clock) else None,
        })
    return {
        "meeting_id": int(row[1]),
        "case_uid": row[0],
        "meeting_no": text(d.get("MTG_MeetingNo")) or str(row[1]),
        "title": text(d.get("MTG_MeetingTitle")),
        "meeting_status": text(d.get("MTG_MeetingStatus")) or str(row[2]),
        "meeting_held": held,
        "not_held_reason": text(d.get("MTG_NotHeldReason")) if held == "NotHeld" else "",
        "attendance": attendance,
        "meeting_date_utc": iso(
            d.get("MTG_persiandate_MeetingStartDateTime")
            or d.get("MTG_MeetingStartDateTime"),
            d.get("MTG_MeetingStartTime"),
        ),
        "risk": None,
        "discussion": text(d.get("MTG_MeetingDiscussionSummary")),
        "parking_lot": text(d.get("MTG_ParkingLot")),
        "secretary_uid": text(d.get("MTG_SecretaryUserUID")),
        "participant_uids": sorted(members(d) - {""}),
        "actions": [],
    }


def _parents(con, scope, cursor=None, limit=MAX_MEETINGS):
    found = []
    last = cursor
    scanned = 0
    while len(found) <= limit:
        args = [scope.get("meeting_process_uid",MEETING_PROCESS)]
        where = "PRO_UID=%s"
        if last is not None:
            where += " AND APP_NUMBER<%s"
            args.append(last)
        # Candidate filter only. Exact membership is checked after safe decoding,
        # before any text is returned to a route, tool or language model.
        if scope["role"] != "SysAdmin":
            uids = sorted(scope["visible_uids"])
            if not uids:
                return found, False
            if len(uids) > 500:
                raise ProductionUnavailable("Manager scope exceeds safe limit")
            where += " AND (" + " OR ".join("APP_DATA LIKE %s" for _ in uids) + ")"
            args += ["%" + uid + "%" for uid in uids]
        rows = query(
            con,
            "SELECT APP_UID,APP_NUMBER,APP_STATUS,APP_DATA FROM APPLICATION WHERE "
            + where
            + " ORDER BY APP_NUMBER DESC LIMIT 10",
            args,
        )
        for row in rows:
            scanned += 1
            if scanned > 20000:
                raise ProductionUnavailable("Native case scan exceeds safe bound")
            d = decode_case(row[3])
            last = int(row[1])
            if scope["role"] != "SysAdmin" and not members(d).intersection(
                scope["visible_uids"]
            ):
                continue
            found.append((_meeting(row, d), d))
            if len(found) > limit:
                return found[:limit], True
        if len(rows) < 10:
            return found, False
    return found, True


def authorized_meetings_page(con, scope, *, cursor=None, limit=50):
    if (
        not isinstance(limit, int)
        or not 1 <= limit <= 50
        or (cursor is not None and (not isinstance(cursor, int) or cursor < 1))
    ):
        raise ValueError("Invalid page")
    rows, more = _parents(con, scope, cursor, limit)
    meetings = [r[0] for r in rows]
    return {
        "meetings": meetings,
        "has_more": more,
        "next_cursor": meetings[-1]["meeting_id"] if more else None,
    }


def authorized_meeting_snapshot(con, scope, *, maximum=MAX_MEETINGS, meeting_id=None):
    if not 1 <= maximum <= MAX_MEETINGS:
        raise ValueError("Invalid limit")
    if meeting_id is None:
        parents, more = _parents(con, scope, limit=maximum)
    else:
        rows = query(con, 'SELECT APP_UID,APP_NUMBER,APP_STATUS,APP_DATA FROM APPLICATION WHERE PRO_UID=%s AND APP_NUMBER=%s', (scope.get("meeting_process_uid",MEETING_PROCESS), meeting_id))
        parents, more = [], False
        for row in rows:
            data = decode_case(row[3])
            if scope['role'] == 'SysAdmin' or members(data).intersection(scope['visible_uids']):
                parents.append((_meeting(row, data), data))
    total = 0
    for m, d in parents:
        try:
            mapping = json.loads(d.get("MTG_ActionCaseMapJson") or "{}")
        except (ValueError, TypeError):
            raise ProductionUnavailable("Invalid parent action map")
        if not isinstance(mapping, dict):
            raise ProductionUnavailable("Invalid parent action map")
        ids = [
            v.get("caseUid")
            for v in mapping.values()
            if isinstance(v, dict)
            and re.fullmatch(r"[a-fA-F0-9]{32}", str(v.get("caseUid", "")))
        ]
        expected = {
            text(cell(a, "MTG_ActionNo", 1)) for a in grid(d.get("MTG_Actions"))
        }
        if expected and expected <= set(mapping) and len(ids) == len(mapping):
            rows = []
            for start in range(0, len(ids), 50):
                chunk = ids[start : start + 50]
                rows.extend(
                    query(
                        con,
                        "SELECT APP_UID,APP_NUMBER,APP_STATUS,APP_DATA,APP_CREATE_DATE FROM APPLICATION WHERE PRO_UID=%s AND APP_UID IN ("
                        + ",".join("%s" for _ in chunk)
                        + ")",
                        (scope.get("action_process_uid",ACTION_PROCESS), *chunk),
                    )
                )
        else:
            rows = query(
                con,
                "SELECT APP_UID,APP_NUMBER,APP_STATUS,APP_DATA,APP_CREATE_DATE FROM APPLICATION WHERE PRO_UID=%s AND APP_DATA LIKE %s ORDER BY APP_NUMBER DESC LIMIT 20001",
                (scope.get("action_process_uid",ACTION_PROCESS), "%" + m["case_uid"] + "%"),
            )
        if len(rows) > 20000:
            raise ProductionUnavailable("Child case bound exceeded")
        children = {}
        for row in rows:
            c = decode_case(row[3])
            if c.get("MTGA_ParentCaseUID") != m["case_uid"]:
                continue
            no = text(c.get("MTGA_ActionNo"))
            if no in children:
                raise ProductionUnavailable(
                    "Duplicate action case; source needs reconciliation"
                )
            children[no] = (row, c)
        for i, a in enumerate(grid(d.get("MTG_Actions"))):
            total += 1
            if total > 20000:
                raise ProductionUnavailable("Action snapshot bound exceeded")
            no = text(cell(a, "MTG_ActionNo", 1))
            child = children.get(no)
            c = child[1] if child else {}
            if not child and text(d.get("MTG_MinutesApproval")) != "Approved":
                continue
            owner = text(c.get("MTGA_OwnerUserUID") or cell(a, "MTG_ActionOwnerUID", 3))
            submissions = history(c.get("MTGA_SubmissionHistoryJson"))
            reviews = history(c.get("MTGA_ReviewHistoryJson"))
            last_sub = submissions[-1] if submissions else {}
            last_review = reviews[-1] if reviews else {}
            submitted = iso(
                last_sub.get("submittedAt") or c.get("MTGA_LastSubmittedAt")
            )
            reviewed = iso(
                last_review.get("reviewedAt") or c.get("MTGA_LastReviewedAt")
            )
            try:
                sub_version = int(last_sub.get("submissionVersion") or 0)
                rev_version = int(last_review.get("submissionVersion") or 0)
            except (ValueError, TypeError):
                raise ProductionUnavailable("Invalid native review version")
            current = bool(
                submitted
                and reviewed
                and (
                    rev_version == sub_version
                    if sub_version > 0
                    else not submitted or reviewed > submitted
                )
            )
            review = (
                text(last_review.get("reviewStatus") or c.get("MTGA_ReviewStatus"))
                if current
                else ""
            )
            progress = (
                last_review.get(
                    "progressPercent", c.get("MTGA_SecretaryProgressPercent")
                )
                if current
                else last_sub.get("progressPercent", c.get("MTGA_ProgressPercent"))
            )
            try:
                progress = int(progress) if progress not in (None, "") else None
            except (ValueError, TypeError):
                progress = None
            closed = review == "Closed"
            m["actions"].append(
                {
                    "action_id": (
                        text(child[0][0]) if child else m["case_uid"] + "-" + no
                    ),
                    "action_no": no or str(i + 1),
                    "description": text(
                        c.get("MTGA_ActionDescription")
                        or cell(a, "MTG_ActionDescription", 2)
                    ),
                    "owner_uid": owner,
                    "owner_name": scope["directory"]
                    .get(owner, {})
                    .get("name", "نامشخص"),
                    "owner_position": text(a.get("MTG_ActionOwnerPosition")),
                    "owner_unit": scope["directory"].get(owner, {}).get("unit")
                    or scope["staff"].get(owner, {}).get("department_name")
                    or "واحد ثبت نشده",
                    "due_at_utc": iso(
                        c.get("MTGA_DueDateTime")
                        or cell(a, "MTG_persiandate_ActionDueDateTime", 5)
                        or cell(a, "MTG_ActionDueDateTime", 5),
                        c.get("MTGA_DueTime"),
                        end_day=True,
                    ),
                    "progress_percent": progress,
                    "is_closed": closed,
                    "status": (
                        "Closed"
                        if closed
                        else (
                            "Rework"
                            if review == "Rework"
                            else "AwaitingReview" if submitted else "Open"
                        )
                    ),
                    "last_submission_at_utc": submitted,
                    "created_at_utc": iso(
                        child[0][4]
                        if child and len(child[0]) > 4
                        else c.get("MTGA_CreatedAt")
                    ),
                    "closed_at_utc": reviewed if closed else None,
                    "priority": text(
                        c.get("MTGA_Priority") or cell(a, "MTG_ActionPriority", 6)
                    ),
                    "submission_history_available": bool(submissions),
                }
            )
    return [r[0] for r in parents], not more


